using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.RedOchre;

/// <summary>
/// Red ochre, lumps of iron-red earth baked in the ash of the Ashlands. Ground into paint it gives a deep red. Model:
/// generated by AssetSource/Tools/make_forage_models.py.
/// </summary>
public class RedOchre : ForageableBase
{
    /// <summary>
    /// Prefab name of the red ochre item.
    /// </summary>
    public const string PrefabName = "WhiteHiltRedOchre";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Red Ochre";

    /// <inheritdoc/>
    protected override string Description => "A lump of iron-red earth baked hard by the fire below. Ground fine, it colours paint a deep red that does not fade.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Flint";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Stone";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 30f,
        ScaleMin = 0.9f,
        ScaleMax = 1.2f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.05f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, IsItem(visualRoot) ? "ochrelump" : "ochre", 0.11f);
    }
}
